<script lang="ts">
 import {onMount} from 'svelte';import {api} from '../lib/api.js';let rows:any[]=[];let status='Loading metrics…';let root='';let contextId='local';async function load(){try{const state=await api<any>('/api/state');if(!state.index){status='Analyze a repository to populate function metrics.';return;}const graph=await api<any>('/api/graph?type=function&limit=10000');root=graph.index.root;contextId=graph.index.contextId;rows=graph.nodes.sort((a:any,b:any)=>(b.crap??-1)-(a.crap??-1));status=`${rows.length} functions`; }catch(error){status=(error as Error).message;}}function open(row:any){window.dispatchEvent(new CustomEvent('atlas:open-file',{detail:{contextId,path:`${root}/${row.path}`.replaceAll('//','/'),pinned:true,line:row.line}}));}onMount(()=>{void load();const refresh=()=>void load();window.addEventListener('atlas:graph-refresh',refresh);return()=>window.removeEventListener('atlas:graph-refresh',refresh);});
</script>
<section class="panel metrics-panel"><header><strong>Function metrics</strong><span>{status}</span></header><div class="metrics-table"><table><thead><tr><th>Function</th><th>File</th><th>Lines</th><th>Complexity</th><th>Coverage</th><th>CRAP</th></tr></thead><tbody>{#each rows as row}<tr ondblclick={()=>open(row)}><td>{row.qualifiedName??row.label}</td><td>{row.path}:{row.line}</td><td>{row.physicalLines??'—'}</td><td>{row.complexity??'—'}</td><td>{row.coverage?`${Math.round(row.coverage.fraction*100)}%${row.coverage.stale?' stale':''}`:'—'}</td><td>{row.crap==null?'—':Number(row.crap).toFixed(1)}</td></tr>{/each}</tbody></table></div></section>
